std::wstring wide(const std::string&s){if(s.empty())return L"";int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),nullptr,0);if(!n)throw std::runtime_error("Файл должен быть сохранён в кодировке UTF-8.");std::wstring w(n,0);MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),n);return w;}
std::string utf8(const std::wstring&s){int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,0,0);std::string t(n,0);WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),t.data(),n,0,0);return t;}
