bool updateShortcut(const fs::path&path){
 if(path.empty())return true;
 if(GetFileAttributesW(path.c_str())==INVALID_FILE_ATTRIBUTES){shortcutStatus="Ярлык не найден. Если вы его перенесли, укажите новое расположение.";return false;}
 IShellLinkW*raw=nullptr;HRESULT hr=CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_IShellLinkW,(void**)&raw);ComPtr<IShellLinkW>link(raw);
 IPersistFile*pfRaw=nullptr;if(SUCCEEDED(hr))hr=link->QueryInterface(IID_IPersistFile,(void**)&pfRaw);ComPtr<IPersistFile>pf(pfRaw);
 if(SUCCEEDED(hr))hr=pf->Load(path.c_str(),STGM_READWRITE);
 wchar_t target[32768]{};if(SUCCEEDED(hr))hr=link->GetPath(target,32768,nullptr,SLGP_RAWPATH);
 if(SUCCEEDED(hr)){std::error_code ec;bool same=fs::equivalent(fs::path(target),base/L"ApolionGacha.exe",ec);if(!same||ec){shortcutStatus="Выберите ярлык именно на ApolionGacha.exe из этой папки.";return false;}}
 if(SUCCEEDED(hr))hr=link->SetIconLocation(iconPath().c_str(),0);
 IPropertyStore*psRaw=nullptr;if(SUCCEEDED(hr))hr=link->QueryInterface(IID_IPropertyStore,(void**)&psRaw);ComPtr<IPropertyStore>ps(psRaw);
 if(SUCCEEDED(hr))hr=property(ps.get(),PKEY_AppUserModel_ID,appId);
 if(SUCCEEDED(hr))hr=ps->Commit();
 if(SUCCEEDED(hr)&&GetFileAttributesW(path.c_str())==INVALID_FILE_ATTRIBUTES){shortcutStatus="Ярлык перемещён или удалён. Укажите его заново.";return false;}
 if(SUCCEEDED(hr))hr=pf->Save(path.c_str(),TRUE);
 if(FAILED(hr)){shortcutStatus="Не удалось обновить ярлык. Проверьте доступ к нему и выберите его заново.";return false;}
 SHChangeNotify(SHCNE_UPDATEITEM,SHCNF_PATHW|SHCNF_FLUSHNOWAIT,path.c_str(),nullptr);shortcutStatus="Иконка выбранного ярлыка обновлена.";return true;
}
void chooseShortcut(){wchar_t path[32768]{};OPENFILENAMEW dlg{sizeof(dlg)};dlg.hwndOwner=windowH;dlg.lpstrFilter=L"Ярлык Windows (*.lnk)\0*.lnk\0\0";dlg.lpstrFile=path;dlg.nMaxFile=32768;dlg.lpstrTitle=L"Укажите созданный вами ярлык Apolion Gacha";dlg.Flags=OFN_FILEMUSTEXIST|OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR|OFN_NODEREFERENCELINKS;if(GetOpenFileNameW(&dlg)){if(lower(fs::path(path).extension().wstring())!=L".lnk")shortcutStatus="Выберите файл ярлыка с расширением .lnk.";else if(updateShortcut(fs::path(path))){shortcutPath=path;saveSettings();}}repaint();}
void setIcon(){auto p=iconPath();HICON i=(HICON)LoadImageW(nullptr,p.c_str(),IMAGE_ICON,0,0,LR_LOADFROMFILE|LR_DEFAULTSIZE);if(i){SendMessageW(windowH,WM_SETICON,ICON_BIG,(LPARAM)i);SendMessageW(windowH,WM_SETICON,ICON_SMALL,(LPARAM)i);if(appIcon)DestroyIcon(appIcon);appIcon=i;}
 IPropertyStore*ps=nullptr;if(SUCCEEDED(SHGetPropertyStoreForWindow(windowH,IID_IPropertyStore,(void**)&ps))){property(ps,PKEY_AppUserModel_RelaunchCommand,L"\""+(base/L"ApolionGacha.exe").wstring()+L"\"");property(ps,PKEY_AppUserModel_RelaunchDisplayNameResource,L"Apolion Gacha");property(ps,PKEY_AppUserModel_RelaunchIconResource,p.wstring()+L",0");property(ps,PKEY_AppUserModel_ID,appId);ps->Commit();ps->Release();}}
