std::vector<fs::path> dataFiles(){std::vector<fs::path> out;for(auto&cat:categories)out.push_back(base/L"data"/fs::u8path(cat+".txt"));auto dir=base/L"data";if(fs::exists(dir))for(auto&it:fs::directory_iterator(dir)){auto p=it.path();if(it.is_regular_file()&&p.extension()==L".txt"&&p.filename()!=L"Шаблоны.txt"&&std::find(out.begin(),out.end(),p)==out.end())out.push_back(p);}return out;}
std::string stamp(){try{std::string out;for(auto p:dataFiles()){out+=p.u8string();if(fs::exists(p))out+=std::to_string(fs::last_write_time(p).time_since_epoch().count())+std::to_string(fs::file_size(p));}auto p=base/L"data"/L"Шаблоны.txt";if(fs::exists(p))out+=std::to_string(fs::last_write_time(p).time_since_epoch().count())+std::to_string(fs::file_size(p));return out;}catch(...){return "!";}}
std::string newCode(){GUID id;CoCreateGuid(&id);wchar_t s[40];StringFromGUID2(id,s,40);return utf8(s);}
void rebuild(){std::set<std::string>sources,fandoms,cats;for(auto&c:categories)cats.insert(c);for(auto&e:entries){cats.insert(e.category);if(!e.enabled)continue;sources.insert(e.source);if(filters.sources.permits({e.source}))fandoms.insert(e.fandom);}std::vector<std::string> all[4];all[0]={sources.begin(),sources.end()};all[1]={fandoms.begin(),fandoms.end()};all[2]={cats.begin(),cats.end()};for(auto&p:presets)all[3].push_back(p.name);for(int i=0;i<4;++i){auto query=lower(wintext(edit[i+3]));auto&v=views[i];v.options.clear();for(auto&s:all[i])if(query.empty()||lower(wide(s)).find(query)!=std::wstring::npos)v.options.push_back(s);int count=(int)(v.list.Height/46);v.offset=std::clamp(v.offset,0,std::max(0,(int)v.options.size()-count));}poolDirty=true;repaint();}
void loadData(bool manual=false){loading=true;std::vector<Entry> next;std::vector<Preset> np;std::string err;std::set<std::string>ids;try{for(auto&path:dataFiles()){auto filename=path.filename().u8string();if(!fs::exists(path)){err+=filename+": файл отсутствует.\n";continue;}try{auto original=read(path);wide(original);auto parsed=parse(original,"=== ЗАПИСЬ ===");for(auto&e:parsed.errors)err+=filename+": "+e+"\n";bool changed=false;std::string localerr;std::vector<Entry> local;for(auto&b:parsed.blocks){try{if(b.fields.count("Код")&&b.fields["Код"].empty()){b.fields["Код"]=newCode();parsed.lines[b.codeLine]="Код: "+b.fields["Код"];changed=true;}auto e=makeEntry(b,path.stem().u8string());if(!ids.insert(e.id).second)throw std::runtime_error("повторяется код «"+e.id+"»; оставьте Код: пустым у новой записи");local.push_back(e);}catch(const std::exception&e){localerr+=filename+", строка "+std::to_string(b.line)+": "+e.what()+"\n";}}err+=localerr;if(changed&&localerr.empty()&&parsed.errors.empty()){if(read(path)!=original)throw std::runtime_error("файл изменился во время чтения; повторите загрузку");auto backup=path;backup+=L".bak";fs::copy_file(path,backup,fs::copy_options::overwrite_existing);auto temp=path;temp+=L".tmp";std::ofstream o(temp,std::ios::binary);o<<"\xef\xbb\xbf";for(auto&line:parsed.lines)o<<line<<"\r\n";o.close();if(!o||!MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("не удалось сохранить автоматически назначенный код");}next.insert(next.end(),local.begin(),local.end());}catch(const std::exception&e){err+=filename+": "+e.what()+"\n";}}
auto p=base/L"data"/L"Шаблоны.txt";try{auto raw=read(p);wide(raw);auto parsed=parse(raw,"=== ШАБЛОН ===");for(auto&e:parsed.errors)err+="Шаблоны.txt: "+e+"\n";std::set<std::string>names;for(auto&b:parsed.blocks){try{auto pr=makePreset(b);if(!names.insert(pr.name).second)throw std::runtime_error("название шаблона повторяется");np.push_back(pr);}catch(const std::exception&e){err+="Шаблоны.txt, строка "+std::to_string(b.line)+": "+e.what()+"\n";}}}catch(const std::exception&e){err+="Шаблоны.txt: "+std::string(e.what())+"\n";}
}catch(const std::exception&e){err+=e.what();}
entries=std::move(next);presets=std::move(np);if(errors!=err)resultOffset=0;errors=err;if(!selectedPreset.empty()){auto it=std::find_if(presets.begin(),presets.end(),[](const Preset&p){return p.name==selectedPreset;});if(it==presets.end())selectedPreset.clear();else{SetWindowTextW(edit[0],wide(decimal(it->lo)).c_str());SetWindowTextW(edit[1],wide(decimal(it->avg)).c_str());SetWindowTextW(edit[2],wide(decimal(it->hi)).c_str());}}
observedStamp=stamp();if(manual)notice=errors.empty()?"Файлы перечитаны. Записей: "+std::to_string(entries.size()):"В файлах есть ошибки. Исправьте их и сохраните файл.";loading=false;rebuild();}
void layout(){RECT r;GetClientRect(windowH,&r);cw=r.right;ch=r.bottom;scale=std::min(cw/1920.f,ch/1080.f);originX=(cw-1920*scale)/2;originY=(ch-1080*scale)/2;HFONT f=CreateFontW(-(int)(26*scale),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Arial");for(int i=0;i<7;++i){RectF q=i<3?RectF(693.f+i*238,56,116,45):views[i-3].search;MoveWindow(edit[i],(int)(originX+q.X*scale),(int)(originY+q.Y*scale),(int)(q.Width*scale),(int)(q.Height*scale),TRUE);SendMessageW(edit[i],WM_SETFONT,(WPARAM)f,TRUE);ShowWindow(edit[i],settings?SW_HIDE:SW_SHOW);}if(editFont)DeleteObject(editFont);editFont=f;repaint();}
void drawPanel(Graphics&g,int i){auto&v=views[i];imageAt(g,std::string(i<2?"holder1-":"holder2-")+(dark?"B.png":"W.png"),v.panel);text(g,v.title,RectF(v.panel.X+20,i<2?45.f:991.f,312,55),36,fg(),true);clickable(g,"refresh-B-W.png",v.reset,10+i);Pen pen(purple,1.5f);g.DrawLine(&pen,v.search.X,v.search.Y+v.search.Height+3,v.search.X+v.search.Width,v.search.Y+v.search.Height+3);
int count=(int)(v.list.Height/46);if(v.options.empty())text(g,"Нет вариантов",RectF(v.list.X+10,v.list.Y+12,280,50),23,fg(),true);for(int j=0;j<count&&v.offset+j<(int)v.options.size();++j){auto&key=v.options[v.offset+j];RectF rr(v.list.X,v.list.Y+j*46,v.list.Width-18,44);int state=0;if(i==3)state=selectedPreset==key?1:0;else {Filter&f=i==0?filters.sources:i==1?filters.fandoms:filters.categories;auto it=f.state.find(key);if(it!=f.state.end())state=it->second;}imageAt(g,state==1?"checkbox-check-B-W.png":state==-1?"checkbox-cross-B-W.png":"checkbox-B-W.png",RectF(rr.X+8,rr.Y+9,24,24));text(g,key,RectF(rr.X+46,rr.Y+6,rr.Width-50,37),26,fg(),false,false,true);hits.push_back({rr,20+i,key});}
if((int)v.options.size()>count){float maxoff=(float)(v.options.size()-count),thumb=std::max(28.f,v.list.Height*count/v.options.size());RectF track(v.list.X+v.list.Width-10,v.list.Y,8,v.list.Height);SolidBrush dim(Color(100,179,33,238)),bright(purple);g.FillRectangle(&dim,track);float top=track.Y+(track.Height-thumb)*v.offset/maxoff;g.FillRectangle(&bright,RectF(track.X,top,track.Width,thumb));hits.push_back({RectF(track.X-5,track.Y,18,track.Height),30+i,""});}}
std::vector<std::pair<std::string,std::string>> helpButtons={
{"edit-B-W.png","Открыть данные — открывает папку «data». Редактируйте файлы обычным Блокнотом и сохраняйте в UTF-8. Изменения подхватываются автоматически; F5 перечитывает файлы вручную."},
{"diceD20-B-W.png","Полный рандом — выбирает из всех включённых записей, игнорируя фильтры источников, фэндомов и категорий. Текущие Мин., Сред., Макс. действуют. Отметки в панелях сохраняются."},
{"dice-B-W.png","Крутка — выбирает одну награду с учётом всех фильтров и текущих границ редкости. Пробел запускает крутку, если курсор не находится в поле ввода."},
{"copy-B-W.png","Копировать — помещает показанный результат в буфер обмена: название, категорию, ранг, редкость, шанс, источник, фэндом и описание. Вставка в другое приложение: Ctrl+V."},
{"option-B-W.png","Настройки — открывает этот экран. Здесь можно сменить тему, иконку и прочитать справку. Выбор темы, иконки и ярлыка сохраняется в source/interface.txt."},
{"refresh-B-W.png","Сброс — снимает все отметки только в своей панели, включая скрытые поиском пункты. Также очищает её поисковую строку. Сброс шаблона сохраняет числовые параметры."},
{"back-B-W.png","Назад — возвращает к гаче, сохраняя текущий результат и выбор. Также можно нажать Esc."}
};
std::vector<std::pair<std::string,std::string>> helpSections={
{"Галочка, крестик и пустой квадрат","Нажатия переключают: пусто → галочка → крестик → пусто. Все отметки фиолетовые. Если в панели есть галочка, подходят только отмеченные галочками варианты. Если галочек нет, подходят все варианты, кроме отмеченных крестиком. Несколько галочек в одной панели означают «любой из них»; условия разных панелей действуют одновременно. Крестик исключает соответствующий источник, фэндом или категорию."},
{"Источники, фэндомы и категории","У каждой записи один источник, одна категория и один фэндом. Версии одного предмета из аниме и сериала оформляются отдельными записями с разными кодами. Список фэндомов ограничивается разрешёнными источниками. Скрытые отметки сохраняются: верните источник или нажмите сброс в панели фэндомов. Поиск меняет только видимость строк и не влияет на крутку. Колёсико прокручивает список под курсором; фиолетовую полосу можно перетаскивать."},
{"Шаблоны и ручные параметры","В панели «Шаблон» можно выбрать только один вариант, без крестика. Другой выбор снимает прежнюю галочку. Шаблон заполняет Мин., Сред., Макс.; изменение этих чисел вручную снимает галочку, но не меняет сам файл шаблонов. Повторное нажатие на выбранный шаблон снимает выбор, сохраняя числа. Создание и изменение шаблонов — в файле «Шаблоны.txt»."},
{"Мин. / Сред. / Макс.","Мин. и Макс. — строгие включительные границы редкости. Сред. — центр предпочтения: запись ближе к нему получает больший вес. Требуется 0 ≤ Мин. ≤ Сред. ≤ Макс. ≤ 10. Дробная часть записывается через точку. При равных границах выпадают только записи с точно такой редкостью. Если подходящих записей нет, приложение сообщает об этом."},
{"Вероятность и повторы","Сначала отбираются подходящие записи, затем для каждой вычисляется вес: 4 в степени −|редкость − Сред.|. Шанс записи равен её весу, делённому на сумму весов всех подходящих записей. При одинаковой редкости шансы одинаковы. Категория и фэндом отдельно не разыгрываются. Порядок строк в файлах не влияет на результат; число записей фэндома влияет на его суммарную вероятность. Повторы разрешены, гаранта и принудительного чередования нет. Процент результата относится к условиям именно той крутки, при которой он выпал."},
{"Файлы записей","Файлы категорий находятся в папке «data»: Предметы.txt, Способности.txt, Существа.txt, Особенности.txt, Навыки.txt. Название файла задаёт категорию; можно добавить собственный .txt с таким же форматом. Скопируйте блок между === ЗАПИСЬ === и === КОНЕЦ ===, измените поля и оставьте Код: пустым у новой записи. Приложение присвоит уникальный код; перед такой записью сохранит прежний файл с расширением .bak. Существующие коды не меняйте. В поле Фэндом укажите одно название. Для другого источника или фэндома создайте отдельную запись. Включено: Нет отключает награду без удаления. Чтобы удалить, уберите блок целиком. Описание может занимать несколько абзацев."},
{"Ошибки и обновление данных","Сохранённые изменения файлов обнаруживаются автоматически примерно за две секунды или при возвращении в приложение. F5 выполняет принудительное перечитывание. Если файл заполнен неверно, в центре появляются имя файла, строка и причина. До исправления крутки приостановлены, чтобы случайно не разыгрывать неполный набор. Пустой файл категории допустим. Храните запасные копии вне папки «data» либо с расширением .bak, чтобы они не стали дополнительной категорией."},
{"Иконка и перенос приложения","PNG-варианты on/off показывают выбранную иконку в настройках. Соответствующий .ico меняет значок окна приложения. Приложение не создаёт ярлыки. Создайте ярлык вручную и нажмите «Указать ярлык» в настройках. Выбранный ярлык будет менять иконку вместе с приложением. После перемещения ярлыка укажите его заново. Встроенный значок самого .exe остаётся № 1. После переноса приложения создайте ярлык с новым путём. Закреплённый на панели задач значок Windows может потребовать открепления и повторного закрепления. Переносите всю папку целиком. Интернет, установка Python и отдельная база данных не нужны."}
};
